namespace {
[[maybe_unused]] const bool g_dataDirectoryBootstrapOk = [] {
    // This check must happen before g_config and g_engine are constructed:
    // both historically open relative paths during static initialization.
    if (dbms::processArgumentsRequestVersion()) {
        std::fprintf(stdout, "dbms %s\n", DBMS_VERSION_STRING);
        std::fflush(stdout);
        std::_Exit(0);
    }
    const auto utility = dbms::requestedDataDirectoryUtility();
    if (utility != dbms::DataDirectoryUtility::None) {
        std::string output;
        std::string error;
        if (!dbms::runDataDirectoryUtility(utility, output, error)) {
            std::fprintf(stderr, "FATAL: %s\n", error.c_str());
            std::fflush(stderr);
            std::_Exit(1);
        }
        std::fprintf(stdout, "%s\n", output.c_str());
        std::fflush(stdout);
        std::_Exit(0);
    }
    std::string error;
    if (!dbms::bootstrapDataDirectory(error)) {
        std::fprintf(stderr, "FATAL: %s\n", error.c_str());
        std::fflush(stderr);
        std::_Exit(1);
    }
    return true;
}();
}

dbms::Config g_config;

namespace {
// Load configuration before the process-global StorageEngine opens databases,
// so bounded statistics snapshots use the configured limit from first load.
const bool g_initialConfigLoadOk = [] {
    if (std::filesystem::exists("dbms.conf") && !g_config.load("dbms.conf")) {
        std::cerr << "FATAL: invalid dbms.conf; refusing to start" << std::endl;
        return false;
    }
    dbms::setSqlStatsMaxEntries(g_config.sqlStatsMaxEntries);
    if (!dbms::notificationManager().configureMaxQueueBytes(
            g_config.maxNotifyQueuePages * static_cast<size_t>(8192))) {
        std::cerr << "FATAL: invalid notification queue configuration"
                  << std::endl;
        return false;
    }
    // TDE must be armed before the StorageEngine (declared right below)
    // opens any data file: recovery reads pages through the buffer pool,
    // and a sealed page without the key loaded fails closed.
    if (!g_config.tdeKeyring.empty()) {
        std::string tdeError;
        if (!dbms::PageCrypto::loadKeyFromFile(g_config.tdeKeyring, tdeError)) {
            std::cerr << "FATAL: TDE keyring error: " << tdeError << std::endl;
            return false;
        }
    }
    return true;
}();
}

StorageEngine g_engine;

// Recursive SELECT helpers call execute() as well.  Structured statement
// results must only be published by the outer statement, never by a nested
// subquery that happens to use the same execution path.
static thread_local unsigned executeDepth = 0;
// A derived table executes recursively, but still needs the inner query's
// typed column descriptor to build its temporary relation. The protocol
// normally accepts results only from depth 1; this scoped depth is the one
// internal metadata-consumer exception.
static thread_local unsigned metadataCaptureDepth = 0;

static bool shouldPublishQueryMetadata() {
    return executeDepth == 1 ||
           (metadataCaptureDepth != 0 && executeDepth == metadataCaptureDepth);
}

static void publishStructuredUtilityResult(
    std::vector<std::string> columns,
    std::vector<std::string> columnTypes,
    std::vector<std::vector<std::string>> rows,
    std::vector<std::vector<bool>> nulls,
    const std::string& commandTag) {
    if (!shouldPublishQueryMetadata()) return;
    dbms::DmlResult result;
    result.available = true;
    result.columns = std::move(columns);
    result.columnTypes = std::move(columnTypes);
    result.rows = std::move(rows);
    result.nulls = std::move(nulls);
    result.commandTag = commandTag;
    dbms::publishLastDmlResult(std::move(result));
}

// ========================================================================
// Slow query log enhancements
// ========================================================================
double g_slowQueryThresholdMs = 100.0;
static constexpr size_t MAX_SLOW_LOG_ENTRIES = 100;
int g_checkpointInterval = 30;  // auto checkpoint every N SQLs

static void invalidatePlanCacheForConfigChange();

// Push Config-backed planner cost parameters into the QueryPlanner cost
// model (custom cost hooks installed by extensions are preserved).
static void syncPlannerCostModel(const dbms::Config& cfg) {
    dbms::QueryPlanner::CostModel cm = dbms::QueryPlanner::costModel();
    cm.seqPageCost = cfg.seqPageCost;
    cm.randomPageCost = cfg.randomPageCost;
    cm.cpuTupleCost = cfg.cpuTupleCost;
    cm.cpuIndexTupleCost = cfg.cpuIndexTupleCost;
    cm.cpuOperatorCost = cfg.cpuOperatorCost;
    cm.enableNestloop = cfg.enableNestloop;
    cm.enableHashJoin = cfg.enableHashJoin;
    cm.enableMergeJoin = cfg.enableMergeJoin;
    dbms::QueryPlanner::setCostModel(cm);
}

static void syncConnectionRuntimeConfig(const dbms::Config& cfg) {
    dbms::getServerStats().maxConnections.store(cfg.maxConnections,
                                                std::memory_order_release);
    dbms::ConnectionPool::instance().configure(
        cfg.poolMode, cfg.poolSize, cfg.maxClientConnections);
}

static bool installReloadedConfig(const dbms::Config& next) {
    // These settings size process-lifetime resources.  A reload must retain
    // their active values; the values already persisted in dbms.conf become
    // effective only when the server starts again.
    dbms::Config applied = next;
    applied.maxConnections = g_config.maxConnections;
    applied.bufferPoolFrames = g_config.bufferPoolFrames;
    applied.maxNotifyQueuePages = g_config.maxNotifyQueuePages;
    if (!next.validate() ||
        !dbms::setSqlStatsMaxEntries(next.sqlStatsMaxEntries)) {
        return false;
    }
    g_config = applied;
    g_slowQueryThresholdMs = applied.slowQueryThresholdMs;
    g_checkpointInterval = applied.checkpointInterval;
    dbms::QueryPlanner::setParallelWorkers(
        applied.maxParallelWorkersPerGather);
    syncPlannerCostModel(applied);
    syncConnectionRuntimeConfig(applied);
    invalidatePlanCacheForConfigChange();
    return true;
}

// ========================================================================
// Query plan cache
// ========================================================================
struct CachedPlanEntry {
    std::string planText;
    std::string dbname;
    std::chrono::steady_clock::time_point cachedAt;
};
static std::map<std::string, CachedPlanEntry> g_queryPlanCache;
static std::mutex g_planCacheMutex;
static size_t g_planCacheHits = 0;
static size_t g_planCacheMisses = 0;
static dbms::PlanCacheEpoch g_planCacheEpoch;

static void clearPlanCacheLocked() {
    g_queryPlanCache.clear();
    g_planCacheHits = 0;
    g_planCacheMisses = 0;
    g_planCacheEpoch.invalidate();
}

static void clearPlanCache() {
    std::lock_guard<std::mutex> lock(g_planCacheMutex);
    clearPlanCacheLocked();
}

// Keep derived plan text out of cache while a catalog/statistics mutation or
// transactional undo is in progress. Invalidate at both boundaries: clearing
// only after DDL lets a concurrent planner publish its pre-DDL plan afterwards.
class PlanCacheChangeGuard {
public:
    explicit PlanCacheChangeGuard(bool active) : active_(active) {
        if (!active_) return;
        std::lock_guard<std::mutex> lock(g_planCacheMutex);
        clearPlanCacheLocked();
        g_planCacheEpoch.beginMutation();
    }
    ~PlanCacheChangeGuard() {
        if (!active_) return;
        std::lock_guard<std::mutex> lock(g_planCacheMutex);
        clearPlanCacheLocked();
        g_planCacheEpoch.endMutation();
    }
    PlanCacheChangeGuard(const PlanCacheChangeGuard&) = delete;
    PlanCacheChangeGuard& operator=(const PlanCacheChangeGuard&) = delete;

private:
    bool active_;
};

static bool changesPlanCache(dbms::SqlCommand command) {
    // CREATE/DROP/ALTER/TRUNCATE/RENAME are the contiguous DDL section of
    // SqlCommand. ALTER SYSTEM persists config; only its eventual reload
    // changes the active planner settings and invalidates their plans.
    if (command >= dbms::SqlCommand::CreateTable &&
        command <= dbms::SqlCommand::Rename &&
        command != dbms::SqlCommand::AlterSystem) return true;
    switch (command) {
        case dbms::SqlCommand::Insert:
        case dbms::SqlCommand::Update:
        case dbms::SqlCommand::Delete:
        case dbms::SqlCommand::Merge:
        case dbms::SqlCommand::Copy:
        case dbms::SqlCommand::Call:
        case dbms::SqlCommand::Do:
        case dbms::SqlCommand::Execute:
        case dbms::SqlCommand::Commit:
        case dbms::SqlCommand::Rollback:
        case dbms::SqlCommand::Abort:
        case dbms::SqlCommand::End:
        case dbms::SqlCommand::RollbackToSavepoint:
        case dbms::SqlCommand::PrepareTransaction:
        case dbms::SqlCommand::CommitPrepared:
        case dbms::SqlCommand::RollbackPrepared:
        case dbms::SqlCommand::Analyze:
        case dbms::SqlCommand::Vacuum:
        case dbms::SqlCommand::Reindex:
        case dbms::SqlCommand::RefreshMaterializedView:
        case dbms::SqlCommand::Cluster:
        case dbms::SqlCommand::ImportForeignSchema:
        case dbms::SqlCommand::Discard:
            return true;
        default:
            return false;
    }
}

static void trimPlanCacheLocked() {
    while (g_queryPlanCache.size() > g_config.queryPlanCacheSize) {
        auto oldest = g_queryPlanCache.begin();
        for (auto it = g_queryPlanCache.begin(); it != g_queryPlanCache.end(); ++it) {
            if (it->second.cachedAt < oldest->second.cachedAt) oldest = it;
        }
        g_queryPlanCache.erase(oldest);
    }
}

// A plan is valid only for the planner settings that produced it. Keep this
// explicit instead of relying on schema invalidation, because SET/ALTER
// SYSTEM can change plan selection without changing catalog metadata.
static std::string planCacheSettingsKey() {
    return ":cfg=" + std::to_string(g_config.workMemKb) +
           ":seq=" + (g_config.enableSeqScan ? "1" : "0") +
           ":hash=" + (g_config.enableHashJoin ? "1" : "0") +
           ":merge=" + (g_config.enableMergeJoin ? "1" : "0") +
           ":parallel=" + std::to_string(g_config.maxParallelWorkersPerGather) +
           ":planner_parallel=" + std::to_string(dbms::QueryPlanner::parallelWorkers());
}

static void invalidatePlanCacheForConfigChange() {
    clearPlanCache();
}

