// ========================================================================
// Row-Level Security helper
// ========================================================================
// ========================================================================
// Utility
// ========================================================================
static string toLower(string s) {
    for (char& c : s) c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
    return s;
}

// Normalize SQL keywords without changing quoted string literals or quoted
// identifiers.  Lowercasing the complete SQL text makes `WHERE name = 'A'`
// disagree with an AST insert that correctly stores 'A'.
static string toLowerSql(string s) {
    const auto protectedBytes = dbms::sqlProtectedBytes(s);
    for (size_t i = 0; i < s.size(); ++i) {
        if (!protectedBytes[i])
            s[i] = static_cast<char>(tolower(static_cast<unsigned char>(s[i])));
    }
    return s;
}

static string trim(const string& s) {
    size_t a = 0;
    while (a < s.size() && isspace(static_cast<unsigned char>(s[a]))) ++a;
    size_t b = s.size();
    while (b > a && isspace(static_cast<unsigned char>(s[b - 1]))) --b;
    return s.substr(a, b - a);
}

static string stripQuotes(const string& s) {
    if (s.size() >= 2 && ((s.front() == '\'' && s.back() == '\'') || (s.front() == '"' && s.back() == '"'))) {
        return s.substr(1, s.size() - 2);
    }
    return s;
}

static string decodeQuotedIdentifier(const string& token) {
    if (token.size() < 2 || token.front() != '"' || token.back() != '"')
        return token;
    string decoded;
    for (size_t i = 1; i + 1 < token.size(); ++i) {
        if (token[i] == '"' && i + 2 < token.size() && token[i + 1] == '"') ++i;
        decoded += token[i];
    }
    return decoded;
}

// Row identity uses SQL output types and NULL bits, never rendered text.
// Keep the first original tuple as the display representative of each key.
static string typedDistinctResultKey(const dbms::DmlResult& result, size_t rowIndex,
                                    const vector<string>& columnTypes) {
    const auto& row = result.rows.at(rowIndex);
    const auto& nulls = result.nulls.at(rowIndex);
    if (nulls.size() != row.size())
        throw dbms::DbError("XX000", "DISTINCT result has an invalid NULL bitmap");
    string key;
    for (size_t i = 0; i < row.size(); ++i) {
        Column column;
        column.dataType = i < columnTypes.size() ? columnTypes[i] : "text";
        for (auto& ch : column.dataType)
            ch = static_cast<char>(tolower(static_cast<unsigned char>(ch)));
        if (column.dataType == "double precision") column.dataType = "double";
        else if (column.dataType == "real") column.dataType = "float";
        key += StorageEngine::groupingValueKey(column, row[i], nulls[i]);
    }
    return key;
}

// Legacy SELECT still renders through a text sink. Quote one header cell so
// the protocol adapter can preserve spaces and embedded double quotes.
static string renderLegacyHeader(const string& header) {
    if (header.find_first_of(" \t\r\n\"") == string::npos) return header;
    string rendered(1, '"');
    for (char c : header) {
        if (c == '"') rendered += '"';
        rendered += c;
    }
    rendered += '"';
    return rendered;
}

// Case-insensitive dictionary order for TEXT sorting, approximating the
// en_US.utf8 locale PostgreSQL uses by default (primary strength).
static int ciTextCompare(const string& a, const string& b) {
    size_t n = min(a.size(), b.size());
    for (size_t i = 0; i < n; ++i) {
        unsigned char ca = tolower((unsigned char)a[i]);
        unsigned char cb = tolower((unsigned char)b[i]);
        if (ca != cb) return ca < cb ? -1 : 1;
    }
    if (a.size() != b.size()) return a.size() < b.size() ? -1 : 1;
    return 0;
}
static pair<set<string>, bool> parseReturningClause(const string& sql, size_t searchStart) {
    size_t retPos = sql.find("returning", searchStart);
    if (retPos == string::npos) return {{}, false};
    string retStr = trim(sql.substr(retPos + 9));
    if (retStr == "*") return {{}, true};
    set<string> cols;
    stringstream rss(retStr);
    string item;
    while (getline(rss, item, ',')) cols.insert(trim(item));
    return {cols, false};
}

static size_t findMatchingParen(const string& sql, size_t start);
static vector<string> tokenize(const string& sql) {
    vector<string> tokens;
    size_t i = 0;
    while (i < sql.size()) {
        while (i < sql.size() && isspace(static_cast<unsigned char>(sql[i]))) ++i;
        if (i >= sql.size()) break;
        if (sql[i] == '(') {
            size_t headEnd = i;
            while (headEnd > 0 && isspace(static_cast<unsigned char>(sql[headEnd - 1])))
                --headEnd;
            const bool functionParen = headEnd > 0 &&
                (isalnum(static_cast<unsigned char>(sql[headEnd - 1])) ||
                 sql[headEnd - 1] == '_' || sql[headEnd - 1] == '"');
            const auto close = functionParen ? string::npos : findMatchingParen(sql, i);
            if (close != string::npos) {
                for (const string suffix : {string("isnotnull"), string("isnull")}) {
                    const size_t after = close + 1 + suffix.size();
                    if (sql.compare(close + 1, suffix.size(), suffix) == 0 &&
                        (after == sql.size() ||
                         !isalnum(static_cast<unsigned char>(sql[after])))) {
                        tokens.push_back(sql.substr(i, after - i));
                        i = after;
                        break;
                    }
                }
                if (i > close) continue;
            }
        }
        if (sql[i] == '(' || sql[i] == ')') {
            tokens.emplace_back(1, sql[i]);
            ++i;
            continue;
        }
        size_t j = i;
        char quote = '\0';
        while (j < sql.size()) {
            const char c = sql[j];
            if (quote != '\0') {
                if (c == quote) {
                    if (j + 1 < sql.size() && sql[j + 1] == quote) {
                        j += 2;  // SQL escaped quote: '' or ""
                        continue;
                    }
                    quote = '\0';
                }
                ++j;
                continue;
            }
            if (c == '\'' || c == '"') {
                quote = c;
                ++j;
                continue;
            }
            if (isspace(static_cast<unsigned char>(c)) || c == '(' || c == ')')
                break;
            ++j;
        }
        tokens.push_back(sql.substr(i, j - i));
        i = j;
    }
    return tokens;
}

// ========================================================================
// CASE WHEN preprocessing forward declaration
// ========================================================================
static string preprocessCaseWhen(string s);

// ========================================================================
// SQL preprocessing
// ========================================================================
static size_t findUnquotedIdentifierWhitespace(const string& text,
                                               size_t start = 0) {
    bool quoted = false;
    for (size_t i = start; i < text.size(); ++i) {
        if (text[i] == '"') {
            if (quoted && i + 1 < text.size() && text[i + 1] == '"') ++i;
            else quoted = !quoted;
        } else if (!quoted && isspace(static_cast<unsigned char>(text[i]))) {
            return i;
        }
    }
    return string::npos;
}

static string foldConstants(const string& s);
static size_t findTopLevelKeyword(const string& sql, const string& kw, size_t startPos);
static string unwrapParenthesizedQuery(const string& sql);
static size_t findTextOutsideQuotes(const string& sql, const string& text,
                                    size_t from = 0);
static size_t findKeywordOutsideQuotes(const string& sql,
                                       const string& keyword,
                                       size_t from = 0);
static size_t findMatchingParen(const string& sql, size_t start);
static string sqlProcessor(string raw, bool /*normalizeBooleanLiterals*/ = false) {
    raw = toLowerSql(raw);
    // Whitespace separates SQL tokens; deleting it joins keywords and names.
    // Normalize runs only outside quotes. Whitespace inside a literal or a
    // quoted identifier is data, including CR/LF and repeated spaces.
    {
        string normalized;
        normalized.reserve(raw.size());
        const auto protectedWhitespace = dbms::sqlProtectedBytes(raw);
        for (size_t i = 0; i < raw.size(); ++i) {
            const char c = raw[i];
            if (protectedWhitespace[i]) {
                normalized += c;
            } else if (isspace(static_cast<unsigned char>(c))) {
                if (normalized.empty() || normalized.back() != ' ') normalized += ' ';
            } else {
                normalized += c;
            }
        }
        raw = std::move(normalized);
    }
    // Trim leading/trailing whitespace
    size_t start = raw.find_first_not_of(' ');
    if (start == string::npos) raw.clear();
    else raw = raw.substr(start, raw.find_last_not_of(' ') - start + 1);
    // A sole final terminator may be followed by comments.  This adapter
    // trims only that legacy execution copy; original SQL remains available
    // for parsing, metadata and diagnostics.  Never cut inside a datum/name.
    const auto protectedBytes = dbms::sqlProtectedBytes(raw);
    size_t terminatorDepth = 0;
    for (size_t i = 0; i < raw.size(); ++i) {
        if (protectedBytes[i]) continue;
        if (raw[i] == '(' || raw[i] == '[') { ++terminatorDepth; continue; }
        if (raw[i] == ')' || raw[i] == ']') {
            if (terminatorDepth) --terminatorDepth;
            continue;
        }
        if (!terminatorDepth && raw[i] == ';' &&
            dbms::skipLeadingSqlTrivia(raw, i + 1) == raw.size()) {
            raw = trim(raw.substr(0, i));
            break;
        }
    }
    // JOIN projections are evaluated from the CASE AST.  The legacy
    // case_when rewrite encodes comparisons as evaluator-only pseudo-tokens
    // (for example >a.id 0), which are invalid column references to the
    // JOIN projection binder.  Keep the SELECT list intact while retaining
    // the legacy rewrite for ON/WHERE clauses after FROM.
    const size_t joinKeyword = findTopLevelKeyword(raw, "join", 0);
    const size_t fromKeyword = findTopLevelKeyword(raw, "from", 0);
    if (toLower(raw).rfind("select ", 0) == 0 &&
        joinKeyword != string::npos && fromKeyword != string::npos &&
        fromKeyword < joinKeyword) {
        raw = raw.substr(0, fromKeyword) +
            preprocessCaseWhen(raw.substr(fromKeyword));
    } else {
        raw = preprocessCaseWhen(raw);
    }
    // Convert array subscript syntax: col[n] -> array_get(col, n)
    {
        string out;
        size_t i = 0;
        while (i < raw.size()) {
            size_t bracketOpen = findTextOutsideQuotes(raw, "[", i);
            if (bracketOpen == string::npos) {
                out += raw.substr(i);
                break;
            }
            // Find column name before bracket
            size_t colStart = bracketOpen;
            while (colStart > i && isspace(static_cast<unsigned char>(raw[colStart - 1]))) --colStart;
            while (colStart > i && (isalnum(static_cast<unsigned char>(raw[colStart - 1])) || raw[colStart - 1] == '_')) --colStart;
            if (colStart == bracketOpen) {
                out += raw[i];
                ++i;
                continue;
            }
            size_t bracketClose = findTextOutsideQuotes(raw, "]", bracketOpen);
            if (bracketClose == string::npos) {
                out += raw.substr(i);
                break;
            }
            string colName = raw.substr(colStart, bracketOpen - colStart);
            string idxStr = trim(raw.substr(bracketOpen + 1, bracketClose - bracketOpen - 1));
            // Skip empty brackets (e.g., type declarations like int[])
            if (idxStr.empty()) {
                out += raw.substr(i, bracketClose - i + 1);
                i = bracketClose + 1;
                continue;
            }
            out += raw.substr(i, colStart - i);
            out += "array_get(" + colName + ", " + idxStr + ")";
            i = bracketClose + 1;
        }
        raw = out;
    }
    // Convert ANY/ALL over an ARRAY literal into IN / NOT IN lists with
    // SQL three-valued semantics (a NULL element makes <> ALL unknown and
    // = ANY still satisfiable by a non-null match).
    {
        auto rewriteQuantifiedArray = [](const string& in) -> string {
            string out = in;
            for (size_t q = 0; ; ) {
                // An ARRAY[...] literal has already been rewritten to
                // array_get(array, e1, e2, ...) upstream; accept both forms.
                const size_t anyPos =
                    findTextOutsideQuotes(out, " any (array", q);
                const size_t allPos =
                    findTextOutsideQuotes(out, " all (array", q);
                bool isAny = true;
                size_t found = anyPos;
                if (anyPos == string::npos ||
                    (allPos != string::npos && allPos < anyPos)) {
                    found = allPos;
                    isAny = false;
                }
                if (found == string::npos) break;
                size_t opEnd = found;
                while (opEnd > 0 && isspace(static_cast<unsigned char>(out[opEnd - 1]))) --opEnd;
                size_t opStart = opEnd;
                while (opStart > 0) {
                    const char c = out[opStart - 1];
                    if (c != '<' && c != '>' && c != '=' && c != '!') break;
                    --opStart;
                }
                if (opStart == opEnd) { q = found + 1; continue; }
                const string op = out.substr(opStart, opEnd - opStart);
                // Element list: either ARRAY[e1,e2] (bracket form) or the
                // already-rewritten array_get(array, e1, e2) call form.
                string elems;
                size_t consumed = 0;
                const size_t bOpen = findTextOutsideQuotes(out, "[", found);
                if (bOpen != string::npos && bOpen > found) {
                    const size_t bClose =
                        findTextOutsideQuotes(out, "]", bOpen);
                    if (bClose == string::npos || bClose < bOpen) { q = found + 1; continue; }
                    elems = out.substr(bOpen + 1, bClose - bOpen - 1);
                    consumed = bClose + 1;
                } else {
                    const size_t pOpen =
                        findTextOutsideQuotes(out, "(", found);
                    if (pOpen == string::npos) { q = found + 1; continue; }
                    size_t depth = 0, pClose = string::npos;
                    for (size_t i2 = pOpen; i2 < out.size(); ++i2) {
                        if (out[i2] == '(') ++depth;
                        else if (out[i2] == ')') { if (--depth == 0) { pClose = i2; break; } }
                    }
                    if (pClose == string::npos) { q = found + 1; continue; }
                    string args = out.substr(pOpen + 1, pClose - pOpen - 1);
                    // drop the leading "array," receiver argument
                    const size_t cm = args.find(',');
                    if (cm == string::npos) { q = found + 1; continue; }
                    elems = args.substr(cm + 1);
                    consumed = pClose + 1;
                }
                // keep commas: the engine's IN-list decoder splits on them
                const string joined = elems;
                const bool neq = (op == "!=" || op == "<>");
                string repl;
                if (isAny && op == "=") {
                    repl = " in (" + joined + ") ";
                } else if (!isAny && neq) {
                    repl = " not in (" + joined + ") ";
                } else { q = found + 1; continue; }
                out = out.substr(0, opStart) + repl + out.substr(consumed);
                q = opStart + repl.size();
            }
            return out;
        };
        raw = rewriteQuantifiedArray(raw);
    }
    // Convert ANY syntax: expr = any(col) -> array_contains(col, expr)
    // Convert ALL syntax: expr = all(col) -> not array_contains(col, expr) with negation (simplified)
    {
        string out;
        size_t i = 0;
        while (i < raw.size()) {
            size_t anyPos = findTextOutsideQuotes(raw, "any(", i);
            size_t allPos = findTextOutsideQuotes(raw, "all(", i);
            size_t foundPos = string::npos;
            bool isAny = true;
            if (anyPos != string::npos && (allPos == string::npos || anyPos < allPos)) {
                foundPos = anyPos;
                isAny = true;
            } else if (allPos != string::npos) {
                foundPos = allPos;
                isAny = false;
            }
            if (foundPos == string::npos) {
                out += raw.substr(i);
                break;
            }
            // Find the operator before ANY/ALL
            size_t opEnd = foundPos;
            while (opEnd > i && isspace(static_cast<unsigned char>(raw[opEnd - 1]))) --opEnd;
            size_t opStart = opEnd;
            while (opStart > i && !isalnum(static_cast<unsigned char>(raw[opStart - 1])) && raw[opStart - 1] != '_' && raw[opStart - 1] != ')' && raw[opStart - 1] != '\'' && raw[opStart - 1] != '"') --opStart;
            if (opStart == opEnd) {
                out += raw[i];
                ++i;
                continue;
            }
            string op = trim(raw.substr(opStart, opEnd - opStart));
            // Find expression before operator
            size_t exprStart = opStart;
            while (exprStart > i && isspace(static_cast<unsigned char>(raw[exprStart - 1]))) --exprStart;
            // Handle parenthesized expressions or simple values
            int parenDepth = 0;
            size_t exprEnd = exprStart;
            while (exprEnd > i) {
                if (raw[exprEnd - 1] == ')') parenDepth++;
                else if (raw[exprEnd - 1] == '(') {
                    if (parenDepth == 0) break;
                    parenDepth--;
                }
                exprEnd--;
                if (parenDepth == 0 && (raw[exprEnd] == ' ' || raw[exprEnd] == ',')) break;
            }
            // Simpler approach: find where the condition starts (after WHERE, AND, OR)
            string beforeAny = raw.substr(i, foundPos - i);
            size_t whereOp = string::npos;
            for (size_t k = beforeAny.size(); k > 0; --k) {
                char c = beforeAny[k - 1];
                if (c == ' ' || c == '(' || c == ',') {
                    whereOp = k;
                    break;
                }
            }
            if (whereOp == string::npos) whereOp = 0;
            string leftExpr = trim(beforeAny.substr(0, whereOp));
            if (!leftExpr.empty()) leftExpr += " ";
            string condExpr = trim(beforeAny.substr(whereOp));
            // Parse array column from any(col) or all(col)
            size_t parenOpen = foundPos + (isAny ? 4 : 4);
            size_t parenClose = raw.find(')', parenOpen);
            if (parenClose == string::npos) {
                out += raw.substr(i);
                break;
            }
            string arrCol = trim(raw.substr(parenOpen, parenClose - parenOpen));
            out += leftExpr;
            if (isAny) {
                out += "array_contains(" + arrCol + ", " + condExpr + ") = 1";
            } else {
                // ALL: simplified - only support = all() as array_contains with negation
                // For other ops, fallback to a less accurate approach
                out += "array_contains(" + arrCol + ", " + condExpr + ") = 0";
            }
            i = parenClose + 1;
        }
        raw = out;
    }
    // Convert IS DISTINCT FROM / IS NOT DISTINCT FROM to equivalent expressions
    {
        auto extractExprBefore = [&](size_t pos) -> std::pair<size_t, std::string> {
            size_t end = pos;
            while (end > 0 && isspace(static_cast<unsigned char>(raw[end - 1]))) end--;
            size_t start = end;
            while (start > 0 && !isspace(static_cast<unsigned char>(raw[start - 1])) && raw[start - 1] != '(' && raw[start - 1] != ',') start--;
            return {start, raw.substr(start, end - start)};
        };
        auto extractExprAfter = [&](size_t pos, size_t len) -> std::pair<size_t, std::string> {
            size_t start = pos + len;
            while (start < raw.size() && isspace(static_cast<unsigned char>(raw[start]))) start++;
            size_t end = start;
            while (end < raw.size() && raw[end] != ',' && raw[end] != ')' && raw[end] != ' ' && raw[end] != ';') end++;
            return {end, raw.substr(start, end - start)};
        };
        // Projection-list occurrences -> scalar function call form.
        {
            size_t fromAt = string::npos;
            {
                size_t scan = 0;
                while ((scan = findTextOutsideQuotes(
                            raw, " from ", scan)) != string::npos) {
                    fromAt = scan;
                    scan += 6;
                }
            }
            const size_t projEnd = (fromAt == string::npos) ? raw.size() : fromAt;
            string head = raw.substr(0, projEnd);
            string tail = (fromAt == string::npos) ? string() : raw.substr(fromAt);
            auto rewriteCalls = [](string h) {
                for (const char* kw : {"is not distinct from", "is distinct from"}) {
                    const size_t kl = strlen(kw);
                    string low;
                    for (char c : h) low += static_cast<char>(tolower(static_cast<unsigned char>(c)));
                    size_t p = 0;
                    while ((p = findTextOutsideQuotes(h, kw, p)) != string::npos) {
                        const bool leftOk = (p == 0) || (!isalnum(static_cast<unsigned char>(h[p - 1])) && h[p - 1] != (char)95);
                        const size_t after = p + kl;
                        const bool rightOk = (after >= low.size()) || (!isalnum(static_cast<unsigned char>(low[after])) && low[after] != (char)95);
                        if (!leftOk || !rightOk) { p += kl; continue; }
                        size_t le = p;
                        while (le > 0 && isspace(static_cast<unsigned char>(h[le - 1]))) --le;
                        size_t ls = le;
                        while (ls > 0) {
                            const char c = h[ls - 1];
                            if (isspace(static_cast<unsigned char>(c))) break;
                            --ls;
                        }
                        size_t rs = after;
                        while (rs < h.size() && isspace(static_cast<unsigned char>(h[rs]))) ++rs;
                        size_t re = rs;
                        while (re < h.size() && !isspace(static_cast<unsigned char>(h[re])) && h[re] != (char)44 && h[re] != (char)41) ++re;
                        if (ls >= le || rs >= re) { p += kl; continue; }
                        const string fn = (kl == 20) ? "isnotdistinct" : "isdistinct";
                        const string call = fn + "(" + h.substr(ls, le - ls) + "," + h.substr(rs, re - rs) + ")";
                        h = h.substr(0, ls) + call + h.substr(re);
                        low.clear();
                        for (char c : h) low += static_cast<char>(tolower(static_cast<unsigned char>(c)));
                        p = ls + call.size();
                    }
                }
                return h;
            };
            head = rewriteCalls(head);
            raw = head + tail;
        }
        size_t pos = 0;
        // IS NOT DISTINCT FROM first (longer match)
        while ((pos = findTextOutsideQuotes(
                    raw, "is not distinct from", pos)) != string::npos) {
            auto [leftStart, leftExpr] = extractExprBefore(pos);
            auto [rightEnd, rightExpr] = extractExprAfter(pos, 20);
            string replacement = "((" + leftExpr + " = " + rightExpr + ") or (" + leftExpr + " is null and " + rightExpr + " is null))";
            raw = raw.substr(0, leftStart) + replacement + raw.substr(rightEnd);
            pos = leftStart + replacement.size();
        }
        pos = 0;
        while ((pos = findTextOutsideQuotes(
                    raw, "is distinct from", pos)) != string::npos) {
            auto [leftStart, leftExpr] = extractExprBefore(pos);
            auto [rightEnd, rightExpr] = extractExprAfter(pos, 16);
            string replacement = "((" + leftExpr + " <> " + rightExpr + ") or (" + leftExpr + " is null and " + rightExpr + " is not null) or (" + leftExpr + " is not null and " + rightExpr + " is null))";
            raw = raw.substr(0, leftStart) + replacement + raw.substr(rightEnd);
            pos = leftStart + replacement.size();
        }
    }
    // substring(v from a [for b]) -> comma form the scalar evaluator
    // decodes; substr(...) is the historical alias and is normalized to
    // substring(...) as well.
    {
        size_t p = 0;
        while (true) {
            const size_t s1 = findTextOutsideQuotes(raw, "substring(", p);
            const size_t s2 = findTextOutsideQuotes(raw, "substr(", p);
            size_t hit = string::npos;
            size_t kwLen = 0;
            if (s1 != string::npos && (s2 == string::npos || s1 <= s2)) { hit = s1; kwLen = 10; }
            else if (s2 != string::npos) { hit = s2; kwLen = 7; }
            if (hit == string::npos) break;
            const size_t openAt = hit;
            size_t close = findMatchingParen(raw, openAt + kwLen - 1);
            if (close == string::npos) { p = openAt + kwLen; continue; }
            string args = raw.substr(openAt + kwLen, close - openAt - kwLen);
            const size_t fAt = findTextOutsideQuotes(args, " from ");
            string repl;
            if (fAt != string::npos) {
                string base = args.substr(0, fAt);
                string rest = args.substr(fAt + 6);
                string lo, ln;
                const size_t forAt = findTextOutsideQuotes(args, " for ", fAt);
                if (forAt != string::npos) {
                    lo = rest.substr(0, forAt - (fAt + 6));
                    ln = rest.substr(forAt - (fAt + 6) + 5);
                } else {
                    lo = rest;
                }
                repl = "substring(" + base + "," + lo;
                if (!ln.empty()) repl += "," + ln;
                repl += ")";
                if (kwLen == 7) repl += " as substr";
            } else if (kwLen == 7) {
                repl = "substring(" + args + ") as substr";
            }
            if (!repl.empty()) {
                raw = raw.substr(0, openAt) + repl + raw.substr(close + 1);
                p = openAt + repl.size();
            } else {
                p = close + 1;
            }
        }
    }
    // position(sub in str) -> comma form (PG accepts both; the comma
    // form is what the argument splitter understands).
    {
        size_t p = 0;
        while ((p = findTextOutsideQuotes(raw, "position(", p)) != string::npos) {
            const size_t openAt = p;
            size_t close = findMatchingParen(raw, openAt + 8);
            if (close == string::npos) { p = openAt + 9; continue; }
            string args = raw.substr(openAt + 9, close - openAt - 9);
            const size_t inAt = findTextOutsideQuotes(args, " in ");
            if (inAt != string::npos) {
                string sub = args.substr(0, inAt);
                string str = args.substr(inAt + 4);
                string repl = "position(" + sub + "," + str + ")";
                raw = raw.substr(0, openAt) + repl + raw.substr(close + 1);
                p = openAt + repl.size();
            } else {
                p = close + 1;
            }
        }
    }
    // The legacy outer SELECT executor consumes LIMIT/OFFSET. Lower only its
    // own FETCH ONLY clause; inner queries are evaluated from their native AST.
    // In particular, quoted text and a nested WITH TIES must remain untouched.
    {
        const size_t fetchPos = findTopLevelKeyword(raw, "fetch", 0);
        if (fetchPos != string::npos) {
            static const regex fetchClause(
                R"(^fetch\s+(?:first|next)(?:\s+([0-9]+))?\s+rows?\s+(only\b|with\s+ties\b))");
            const string tail = raw.substr(fetchPos);
            smatch fetchMatch;
            if (regex_search(tail, fetchMatch, fetchClause)) {
                if (fetchMatch[2].str() != "only") {
                    if (findTopLevelKeyword(raw, "order by", 0) ==
                        string::npos) {
                        throw runtime_error(
                            "FETCH WITH TIES requires ORDER BY "
                            "(SQLSTATE 42601)");
                    }
                    // Keep the tail intact here.  The set-operation executor
                    // applies FETCH after combining its operands; ordinary
                    // SELECT lowering handles its narrower structured subset
                    // after statement dispatch.
                } else {
                    const string count = fetchMatch[1].matched
                        ? fetchMatch[1].str() : "1";
                    string replacement = "limit " + count;
                    size_t replacePos = fetchPos;
                    const size_t offsetPos =
                        findTopLevelKeyword(raw, "offset", 0);
                    bool canRewrite = true;
                    if (offsetPos != string::npos && offsetPos < fetchPos) {
                        static const regex offsetClause(
                            R"(^offset\s+([0-9]+)(?:\s+rows?)?\s*$)");
                        const string offsetText =
                            raw.substr(offsetPos, fetchPos - offsetPos);
                        smatch offsetMatch;
                        canRewrite = regex_match(
                            offsetText, offsetMatch, offsetClause);
                        if (canRewrite) {
                            replacement += " offset " +
                                offsetMatch[1].str();
                            replacePos = offsetPos;
                        }
                    }
                    if (canRewrite) {
                        raw.replace(
                            replacePos,
                            fetchPos + fetchMatch.length() - replacePos,
                            replacement);
                    }
                }
            }
        }
    }
    return raw;
}

// ========================================================================
// CASE WHEN preprocessing: "case when a then b when c then d else e end"
//                         → "case_when(a,b,c,d,e)"
// ========================================================================
static string normalizeCaseCondition(string s) {
    s = trim(s);
    static const char* ops[] = {"<<", ">>", "<^", ">^", "<@", "&&", ">=", "<=", "!=", "<>", ">", "<", "="};
    for (const char* op : ops) {
        size_t len = strlen(op);
        size_t pos = s.find(op);
        if (pos != string::npos) {
            string before = trim(s.substr(0, pos));
            string after = trim(s.substr(pos + len));
            return string(op) + before + " " + after;
        }
    }
    size_t isnotPos = s.find("is not null");
    if (isnotPos != string::npos) {
        return "isnotnull " + trim(s.substr(0, isnotPos));
    }
    size_t isPos = s.find("is null");
    if (isPos != string::npos) {
        return "isnull " + trim(s.substr(0, isPos));
    }
    // "col not like pat" must be detected before "like" (which would
    // otherwise read the column as "col not")
    size_t notLikePos = s.find("not like ");
    if (notLikePos != string::npos) {
        string before = trim(s.substr(0, notLikePos));
        string after = trim(s.substr(notLikePos + 9));
        return "notlike" + before + " " + after;
    }
    size_t likePos = s.find("like");
    if (likePos != string::npos) {
        string before = trim(s.substr(0, likePos));
        string after = trim(s.substr(likePos + 4));
        return "like" + before + " " + after;
    }
    // "col not between lo and hi" -> negated range pair
    size_t notBtwPos = s.find("not between ");
    if (notBtwPos != string::npos) {
        string before = trim(s.substr(0, notBtwPos));
        string rest = trim(s.substr(notBtwPos + 12));
        size_t andPos = rest.find(" and ");
        if (andPos != string::npos) {
            string lo = trim(rest.substr(0, andPos));
            string hi = trim(rest.substr(andPos + 5));
            return "notbetween" + before + " " + lo + " " + hi;
        }
    }
    size_t btwPos = s.find("between ");
    if (btwPos != string::npos) {
        string before = trim(s.substr(0, btwPos));
        string rest = trim(s.substr(btwPos + 8));
        size_t andPos = rest.find(" and ");
        if (andPos != string::npos) {
            string lo = trim(rest.substr(0, andPos));
            string hi = trim(rest.substr(andPos + 5));
            return "between" + before + " " + lo + " " + hi;
        }
    }
    return s;
}

static string preprocessCaseWhen(string s) {
    size_t pos = 0;
    while (true) {
        // SIMPLE case ("case <expr> when v1 then r1 ..."): rewrite to
        // searched form by expanding each WHEN value into
        // "<expr> = <value>" before the searched-case loop below.
        size_t simplePos = pos;
        while (true) {
            size_t cp = findTextOutsideQuotes(s, "case ", simplePos);
            if (cp == string::npos) break;
            size_t after = cp + 5;
            if (s.compare(after, 4, "when") == 0) { simplePos = cp + 5; continue; }
            size_t firstWhen = s.find(" when ", after);
            if (firstWhen == string::npos) { simplePos = cp + 5; continue; }
            size_t endPos2 = s.find(" end", firstWhen);
            if (endPos2 == string::npos) { simplePos = cp + 5; continue; }
            string operand = trim(s.substr(after, firstWhen - after));
            string body = s.substr(firstWhen + 6, endPos2 - firstWhen - 6);
            string rebuilt;
            size_t cur = 0;
            while (cur < body.size()) {
                size_t thenPos2 = body.find("then", cur);
                if (thenPos2 == string::npos) { rebuilt += body.substr(cur); break; }
                string val = trim(body.substr(cur, thenPos2 - cur));
                size_t nextWhen2 = body.find("when", thenPos2 + 4);
                string tail;
                if (nextWhen2 == string::npos) tail = body.substr(thenPos2 + 4);
                else tail = body.substr(thenPos2 + 4, nextWhen2 - thenPos2 - 4);
                rebuilt += "when " + operand + " = " + val + " then " + trim(tail) + " ";
                if (nextWhen2 == string::npos) break;
                cur = nextWhen2 + 4;
            }
            s = s.substr(0, cp) + "case " + trim(rebuilt) + s.substr(endPos2 + 1);
            simplePos = cp + 4;
        }
        size_t casePos = findTextOutsideQuotes(s, "case when", pos);
        if (casePos == string::npos) break;
        size_t endPos = s.find("end", casePos);
        if (endPos == string::npos) break;
        string content = trim(s.substr(casePos + 9, endPos - casePos - 9));

        vector<pair<string, string>> whenThen;
        string elseVal;
        size_t curr = 0;
        while (curr < content.size()) {
            size_t thenPos = content.find("then", curr);
            if (thenPos == string::npos) break;
            string cond = normalizeCaseCondition(content.substr(curr, thenPos - curr));

            size_t nextWhen = content.find("when", thenPos + 4);
            size_t elsePos = content.find("else", thenPos + 4);

            if (elsePos != string::npos && (nextWhen == string::npos || elsePos < nextWhen)) {
                string thenVal = trim(content.substr(thenPos + 4, elsePos - thenPos - 4));
                whenThen.emplace_back(cond, thenVal);
                elseVal = trim(content.substr(elsePos + 4));
                break;
            } else if (nextWhen != string::npos) {
                string thenVal = trim(content.substr(thenPos + 4, nextWhen - thenPos - 4));
                whenThen.emplace_back(cond, thenVal);
                curr = nextWhen + 4;
            } else {
                string thenVal = trim(content.substr(thenPos + 4));
                whenThen.emplace_back(cond, thenVal);
                break;
            }
        }

        string replacement = "case_when(";
        for (size_t i = 0; i < whenThen.size(); ++i) {
            if (i > 0) replacement += ",";
            replacement += whenThen[i].first + "," + whenThen[i].second;
        }
        if (!elseVal.empty()) {
            if (!whenThen.empty()) replacement += ",";
            replacement += elseVal;
        }
        replacement += ")";

        s = s.substr(0, casePos) + replacement + s.substr(endPos + 3);
        pos = casePos + replacement.size();
    }
    return s;
}

// ========================================================================
// Scalar function helpers
// ========================================================================
static bool isScalarFunc(const string& name) {
    static const set<string> scalars = {"length", "char_length", "character_length", "upper", "lower", "trim", "substring", "concat",
                                         "abs", "round", "trunc", "ceil", "floor",
                                         "now", "current_timestamp", "extract", "date_part", "timezone",
                                         "year", "month", "day",
                                         "hour", "minute", "second",
                                         "case_when", "cast", "convert",
                                         "to_number", "to_char", "to_date", "to_timestamp",
        "justify_hours", "justify_days", "justify_interval",
                                         "coalesce", "nullif",
                                         "replace", "position", "instr", "strpos", "overlay", "translate",
                                         "power", "sqrt", "mod", "div", "gcd", "lcm", "width_bucket",
                                         "ln", "log", "exp", "random", "rand",
                                          "concat", "concat_ws", "initcap",
                                         "lpad", "rpad", "reverse", "left", "right", "repeat", "btrim", "ltrim", "rtrim",
                                         "sign", "greatest", "least", "if", "iif",
                                         "date_add", "date_sub",
                                         "datediff", "date_trunc", "date_format",
                                         "age",
                                         "json_extract", "json_value",
                                         "jsonb_extract", "jsonb_extract_text",
                                         "jsonb_contains", "jsonb_exists", "jsonb_pretty",
                                         "sin", "cos", "tan",
                                         "split_part",
                                         "uuid_generate", "gen_random_uuid",
                                         "uuidv4", "uuidv7",
                                         "uuid_extract_version",
                                         "uuid_extract_timestamp",
                                         "array_get", "array_length", "array_contains",
                                         "array_position", "array_dims", "cardinality",
                                         "unnest",
                                         "pg_notify", "pg_notification_queue_usage",
                                         "pg_listening_channels",
                                         "subquery",
                         "exists",
                                         "is_null", "is_not_null",
                                         "isdistinct", "isnotdistinct",
                                         "current_user", "session_user"};
    return scalars.find(name) != scalars.end();
}

static vector<string> splitSelectColumns(const string& s) {
    vector<string> cols;
    const auto protectedBytes = dbms::sqlProtectedBytes(s);
    size_t i = 0;
    int parenDepth = 0;
    string current;
    while (i < s.size()) {
        if (!protectedBytes[i] && (s[i] == '(' || s[i] == '[')) parenDepth++;
        else if (!protectedBytes[i] && (s[i] == ')' || s[i] == ']')) parenDepth--;
        else if (!protectedBytes[i] && s[i] == ',' && parenDepth == 0) {
            cols.push_back(trim(current));
            current.clear();
            ++i;
            continue;
        }
        current += s[i];
        ++i;
    }
    if (!current.empty()) cols.push_back(trim(current));
    return cols;
}

// Find a keyword at top-level, skipping parentheses, strings and quoted identifiers.
// Returns string::npos if not found. The match boundary is checked at word level.
static size_t findTopLevelKeyword(const string& sql, const string& kw, size_t startPos = 0) {
    int depth = 0;
    const auto protectedBytes = dbms::sqlProtectedBytes(sql);
    size_t klen = kw.size();
    if (!klen) return string::npos;
    auto isIdentifierChar = [](unsigned char ch) {
        return isalnum(ch) || ch == '_' || ch == '$';
    };
    for (size_t i = startPos; i < sql.size(); ++i) {
        char c = sql[i];
        if (protectedBytes[i]) continue;
        if (c == '(') { depth++; continue; }
        if (c == ')') { depth--; continue; }
        if (depth == 0 && i + klen <= sql.size() && sql.compare(i, klen, kw) == 0 &&
            none_of(protectedBytes.begin() + i, protectedBytes.begin() + i + klen,
                    [](bool value) { return value; })) {
            bool leftOk = (i == 0) ||
                !isIdentifierChar(static_cast<unsigned char>(sql[i - 1]));
            bool rightOk = (i + klen == sql.size()) ||
                !isIdentifierChar(static_cast<unsigned char>(sql[i + klen]));
            if (leftOk && rightOk) return i;
        }
    }
    return string::npos;
}

static vector<string> splitFuncArgs(const string& s) {
    vector<string> args;
    size_t i = 0;
    while (i < s.size()) {
        while (i < s.size() && isspace(static_cast<unsigned char>(s[i]))) ++i;
        if (i >= s.size()) break;
        string arg;
        if (s[i] == '\'') {
            arg += s[i++];
            while (i < s.size() && s[i] != '\'') arg += s[i++];
            if (i < s.size()) arg += s[i++];
        } else {
            int depth = 0;
            while (i < s.size()) {
                char ch = s[i];
                if (ch == '(') ++depth;
                else if (ch == ')') { if (depth > 0) --depth; }
                else if (ch == ',' && depth == 0) break;
                arg += ch;
                ++i;
            }
        }
        args.push_back(trim(arg));
        if (i < s.size() && s[i] == ',') ++i;
    }
    return args;
}

static vector<string> splitTopLevelComma(const string& s);

static bool isStandaloneValuesTypedLiteral(const string& expression) {
    const string value = trim(expression);
    size_t keywordEnd = 0;
    while (keywordEnd < value.size() &&
           isalpha(static_cast<unsigned char>(value[keywordEnd]))) {
        ++keywordEnd;
    }
    string keyword = value.substr(0, keywordEnd);
    for (char& c : keyword) {
        c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
    }
    static const set<string> typedLiteralKeywords = {
        "boolean", "date", "interval", "numeric", "time",
        "timestamp", "timestamptz"
    };
    if (!typedLiteralKeywords.count(keyword) || keywordEnd == value.size() ||
        !isspace(static_cast<unsigned char>(value[keywordEnd]))) {
        return false;
    }
    size_t quote = keywordEnd;
    while (quote < value.size() &&
           isspace(static_cast<unsigned char>(value[quote]))) {
        ++quote;
    }
    if (quote >= value.size() || value[quote] != '\'') return false;
    for (size_t i = quote + 1; i < value.size(); ++i) {
        if (value[i] != '\'') continue;
        if (i + 1 < value.size() && value[i + 1] == '\'') {
            ++i;
            continue;
        }
        return i + 1 == value.size();
    }
    return false;
}

static bool parseValuesRows(const string& valuesPart,
                            vector<vector<string>>& rows,
                            string& error) {
    size_t i = 0;
    size_t expectedCols = 0;
    while (i < valuesPart.size()) {
        while (i < valuesPart.size() && isspace(static_cast<unsigned char>(valuesPart[i]))) ++i;
        if (i >= valuesPart.size()) break;
        if (valuesPart[i] != '(') {
            error = "SQL syntax error: VALUES requires parenthesized rows";
            return false;
        }

        ++i;
        string inner;
        int parenDepth = 0;
        bool inQuote = false;
        bool closed = false;
        for (; i < valuesPart.size(); ++i) {
            char c = valuesPart[i];
            if (c == '\'') {
                inner += c;
                if (inQuote && i + 1 < valuesPart.size() && valuesPart[i + 1] == '\'') {
                    inner += valuesPart[++i];
                    continue;
                }
                inQuote = !inQuote;
                continue;
            }
            if (!inQuote) {
                if (c == '(' || c == '[') {
                    ++parenDepth;
                } else if (c == ')' || c == ']') {
                    if (parenDepth == 0) {
                        if (c != ')') {
                            error = "SQL syntax error: unmatched bracket in VALUES row";
                            return false;
                        }
                        closed = true;
                        ++i;
                        break;
                    }
                    --parenDepth;
                }
            }
            inner += c;
        }
        if (!closed) {
            error = "SQL syntax error: unterminated VALUES row";
            return false;
        }

        vector<string> cells = splitTopLevelComma(inner);
        if (cells.empty() ||
            any_of(cells.begin(), cells.end(), [](const string& cell) {
                return trim(cell).empty();
            })) {
            error = "SQL syntax error: VALUES row cannot be empty";
            return false;
        }
        if (rows.empty()) {
            expectedCols = cells.size();
        } else if (cells.size() != expectedCols) {
            error = "VALUES lists must all be the same length";
            return false;
        }
        rows.push_back(std::move(cells));

        while (i < valuesPart.size() && isspace(static_cast<unsigned char>(valuesPart[i]))) ++i;
        if (i >= valuesPart.size()) break;
        if (valuesPart[i] != ',') {
            error = "SQL syntax error: expected comma between VALUES rows";
            return false;
        }
        ++i;
        while (i < valuesPart.size() &&
               isspace(static_cast<unsigned char>(valuesPart[i]))) {
            ++i;
        }
        if (i >= valuesPart.size()) {
            error = "SQL syntax error: trailing comma after VALUES row";
            return false;
        }
    }
    if (rows.empty()) {
        error = "SQL syntax error: VALUES requires at least one row";
        return false;
    }
    return true;
}

static bool validateValuesExpression(const string& expression,
                                     string& error,
                                     string& sqlState) {
    string lowered = trim(expression);
    for (char& c : lowered) {
        c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
    }
    if (lowered == "default") {
        error = "DEFAULT is not allowed in a standalone VALUES list";
        sqlState = "42601";
        return false;
    }
    if (lowered.rfind("array[", 0) == 0 ||
        lowered.rfind("row(", 0) == 0) {
        error = "VALUES expression is not supported";
        sqlState = "0A000";
        return false;
    }
    if (isStandaloneValuesTypedLiteral(expression)) return true;

    dbms::SQLParser parser;
    auto parsed = parser.parse("SELECT " + expression);
    const auto* select = parsed.success
        ? dynamic_cast<const dbms::SelectStmt*>(parsed.stmt.get()) : nullptr;
    if (!select || select->selectList.size() != 1 ||
        !select->selectList.front().expr ||
        !select->selectList.front().alias.empty() || select->fromClause ||
        select->whereClause || !select->groupBy.empty() || select->having ||
        !select->orderBy.empty() || select->limit || select->offset) {
        error = parsed.error.empty()
            ? "invalid expression in VALUES row" : parsed.error;
        sqlState = "42601";
        return false;
    }

    string unboundColumn;
    bool unsupported = false;
    std::function<void(const dbms::Expr*)> inspect =
        [&](const dbms::Expr* node) {
            if (!node || !unboundColumn.empty() || unsupported) return;
            switch (node->type) {
                case dbms::ExprType::Literal:
                    return;
                case dbms::ExprType::ColumnRef: {
                    const auto* column =
                        static_cast<const dbms::ColumnRefExpr*>(node);
                    string name = column->column;
                    for (char& c : name) {
                        c = static_cast<char>(
                            tolower(static_cast<unsigned char>(c)));
                    }
                    static const set<string> available = {
                        "current_user", "session_user", "user",
                        "current_date", "current_timestamp", "localtimestamp"
                    };
                    static const set<string> knownButUnsupported = {
                        "current_catalog", "current_role", "current_schema",
                        "current_time", "localtime"
                    };
                    if (column->schema.empty() && column->table.empty() &&
                        available.count(name)) {
                        return;
                    }
                    if (column->schema.empty() && column->table.empty() &&
                        knownButUnsupported.count(name)) {
                        unsupported = true;
                        return;
                    }
                    unboundColumn = column->toString();
                    return;
                }
                case dbms::ExprType::UnaryOp:
                    inspect(static_cast<const dbms::UnaryOpExpr*>(node)
                                ->operand.get());
                    return;
                case dbms::ExprType::BinaryOp: {
                    const auto* binary =
                        static_cast<const dbms::BinaryOpExpr*>(node);
                    inspect(binary->left.get());
                    inspect(binary->right.get());
                    return;
                }
                case dbms::ExprType::FunctionCall: {
                    const auto* call =
                        static_cast<const dbms::FunctionCallExpr*>(node);
                    string name = call->funcName;
                    for (char& c : name) {
                        c = static_cast<char>(
                            tolower(static_cast<unsigned char>(c)));
                    }
                    static const set<string> aggregateOrSetReturning = {
                        "array_agg", "avg", "bit_and", "bit_or",
                        "bool_and", "bool_or", "count", "every",
                        "generate_series", "json_agg", "jsonb_agg",
                        "max", "min", "string_agg", "sum", "unnest",
                        "xmlagg"
                    };
                    if (aggregateOrSetReturning.count(name) ||
                        call->distinct || !call->orderBy.empty() ||
                        call->filter || call->hasOver) {
                        unsupported = true;
                        return;
                    }
                    for (const auto& arg : call->args) inspect(arg.get());
                    for (const auto& arg : call->namedArgs) {
                        inspect(arg.value.get());
                    }
                    return;
                }
                case dbms::ExprType::CastExpr:
                    inspect(static_cast<const dbms::CastExpr*>(node)
                                ->operand.get());
                    return;
                case dbms::ExprType::CaseExpr: {
                    const auto* caseExpr =
                        static_cast<const dbms::CaseExpr*>(node);
                    inspect(caseExpr->switchExpr.get());
                    for (const auto& clause : caseExpr->whenClauses) {
                        inspect(clause.first.get());
                        inspect(clause.second.get());
                    }
                    inspect(caseExpr->elseExpr.get());
                    return;
                }
                case dbms::ExprType::ArrayExpr:
                    for (const auto& element :
                         static_cast<const dbms::ArrayExpr*>(node)->elements) {
                        inspect(element.get());
                    }
                    return;
                case dbms::ExprType::RowExpr:
                    for (const auto& element :
                         static_cast<const dbms::RowExpr*>(node)->elements) {
                        inspect(element.get());
                    }
                    return;
                case dbms::ExprType::Subquery:
                case dbms::ExprType::Parameter:
                case dbms::ExprType::A_Star:
                    unsupported = true;
                    return;
            }
        };
    inspect(select->selectList.front().expr.get());
    if (!unboundColumn.empty()) {
        string lower = unboundColumn;
        for (char& c : lower) {
            c = static_cast<char>(tolower(static_cast<unsigned char>(c)));
        }
        if (lower == "default") {
            error = "DEFAULT is not allowed in a standalone VALUES list";
            sqlState = "42601";
        } else {
            error = "column \"" + unboundColumn + "\" does not exist";
            sqlState = "42703";
        }
        return false;
    }
    if (unsupported) {
        error = "VALUES expression is not supported";
        sqlState = "0A000";
        return false;
    }
    return true;
}

static string inferValuesExpressionType(const string& expression) {
    return dbms::ExprHelper::inferValuesResultType(expression);
}

static string canonicalValuesType(string type) {
    return dbms::ExprHelper::canonicalResultTypeName(std::move(type));
}

static bool isSupportedValuesTarget(const string& type) {
    static const set<string> supported = {
        "boolean", "smallint", "integer", "bigint", "numeric", "real",
        "double precision", "character", "character varying", "text",
        "date", "timestamp", "timestamptz", "uuid", "bytea",
        "int4range", "int8range", "numrange", "daterange", "tsrange",
        "tstzrange", "name"
    };
    return supported.count(type) != 0;
}

static bool resolveValuesColumnType(const vector<string>& inputTypes,
                                    string& resultType,
                                    string& error) {
    return dbms::ExprHelper::resolveValuesResultType(
        inputTypes, resultType, error);
}

static bool executeValuesStatement(const string& sql, const Session& session) {
    const string statement = trim(sql);
    string rest = trim(statement.substr(6));
    if (!rest.empty() && rest.back() == ';') {
        rest = trim(rest.substr(0, rest.size() - 1));
    }
    vector<vector<string>> rows;
    string error;
    if (!parseValuesRows(rest, rows, error)) {
        cout << "ERROR: " << error << " (SQLSTATE 42601)" << endl;
        return true;
    }

    const size_t width = rows.front().size();
    vector<vector<string>> inferredTypes(
        rows.size(), vector<string>(width));
    for (size_t row = 0; row < rows.size(); ++row) {
        for (size_t col = 0; col < width; ++col) {
            string sqlState;
            if (!validateValuesExpression(
                    rows[row][col], error, sqlState)) {
                cout << "ERROR: " << error << " (SQLSTATE "
                     << sqlState << ")" << endl;
                return true;
            }
            inferredTypes[row][col] =
                inferValuesExpressionType(rows[row][col]);
        }
    }

    vector<string> columnTypes(width);
    for (size_t col = 0; col < width; ++col) {
        vector<string> inputs;
        inputs.reserve(rows.size());
        for (size_t row = 0; row < rows.size(); ++row) {
            inputs.push_back(inferredTypes[row][col]);
        }
        if (!resolveValuesColumnType(inputs, columnTypes[col], error)) {
            cout << "ERROR: " << error << " (SQLSTATE 42804)" << endl;
            return true;
        }
        if (!isSupportedValuesTarget(columnTypes[col])) {
            cout << "ERROR: VALUES type " << columnTypes[col]
                 << " is not supported (SQLSTATE 0A000)" << endl;
            return true;
        }
    }

    vector<vector<string>> values;
    vector<vector<bool>> nulls;
    values.reserve(rows.size());
    nulls.reserve(rows.size());
    for (size_t row = 0; row < rows.size(); ++row) {
        vector<string> valueRow;
        vector<bool> nullRow;
        valueRow.reserve(width);
        nullRow.reserve(width);
        for (size_t col = 0; col < width; ++col) {
            string expression = trim(rows[row][col]);
            string lower = expression;
            for (char& c : lower) {
                c = static_cast<char>(
                    tolower(static_cast<unsigned char>(c)));
            }
            if (lower == "user") expression = "current_user";
            if (columnTypes[col] == "name" &&
                inferredTypes[row][col] != "name") {
                cout << "ERROR: VALUES coercion to name is not supported "
                     << "(SQLSTATE 0A000)" << endl;
                return true;
            }
            const string evaluatedExpression =
                "CAST((" + expression + ") AS " + columnTypes[col] + ")";
            const auto evaluated = dbms::ExprHelper::evalString(
                evaluatedExpression, {}, {}, session.currentDB,
                session.username);
            if (!evaluated.ok) {
                cout << "ERROR: "
                     << (evaluated.error.empty()
                             ? "cannot evaluate VALUES expression"
                             : evaluated.error)
                     << endl;
                return true;
            }
            const string actualType =
                canonicalValuesType(evaluated.typeName);
            if (actualType != columnTypes[col]) {
                cout << "ERROR: VALUES coercion to " << columnTypes[col]
                     << " is not supported (SQLSTATE 0A000)" << endl;
                return true;
            }
            valueRow.push_back(evaluated.isNull ? string{} : evaluated.value);
            nullRow.push_back(evaluated.isNull);
        }
        values.push_back(std::move(valueRow));
        nulls.push_back(std::move(nullRow));
    }

    vector<string> columns;
    columns.reserve(width);
    for (size_t col = 0; col < width; ++col) {
        columns.push_back("column" + std::to_string(col + 1));
    }
    publishStructuredUtilityResult(
        columns, columnTypes, values, nulls,
        "SELECT " + std::to_string(values.size()));

    for (size_t col = 0; col < columns.size(); ++col) {
        if (col > 0) cout << ' ';
        cout << columns[col];
    }
    cout << endl;
    for (size_t row = 0; row < values.size(); ++row) {
        for (size_t col = 0; col < width; ++col) {
            if (col > 0) cout << ' ';
            cout << (nulls[row][col] ? "NULL" : values[row][col]);
        }
        cout << endl;
    }
    return false;
}

